:scope .chapter-container {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #1a1a1a);
  background: var(--paper, #ffffff);
  line-height: 1.6;
  padding: 2rem 1rem;
  max-width: 900px;
  margin: 0 auto;
}

:scope .chapter-header {
  border-bottom: 2px solid var(--line, #e0e0e0);
  margin-bottom: 2rem;
  padding-bottom: 1rem;
}

:scope .chapter-header h1 {
  font-size: 1.8rem;
  color: var(--accent, #0055aa);
  margin: 0 0 0.5rem 0;
}

:scope .chapter-takeaway {
  font-size: 1rem;
  color: var(--muted, #666);
  font-style: italic;
}

:scope .content-block {
  margin-bottom: 3rem;
}

:scope .content-block h2 {
  font-size: 1.5rem;
  border-left: 4px solid var(--accent, #0055aa);
  padding-left: 1rem;
  margin-bottom: 1.5rem;
}

/* Stepper Interaction */
:scope .tech-stack-interaction {
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 8px;
  padding: 1.5rem;
  background: #f9f9f9;
}

:scope .interaction-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
  gap: 1rem;
}

:scope .control-btn {
  background: var(--accent, #0055aa);
  color: #fff;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}

:scope .control-btn:disabled {
  background: var(--muted, #ccc);
  cursor: not-allowed;
}

:scope .step-indicators {
  display: flex;
  gap: 0.5rem;
}

:scope .step-indicator {
  background: transparent;
  border: 1px solid var(--accent, #0055aa);
  color: var(--accent, #0055aa);
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
}

:scope .step-indicator.active {
  background: var(--accent, #0055aa);
  color: #fff;
}

:scope .visual-stage {
  background: #fff;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  margin-bottom: 1.5rem;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

:scope #tech-svg {
  width: 100%;
  height: auto;
  max-height: 300px;
}

:scope .content-panel h3 {
  font-size: 1.2rem;
  margin: 0 0 0.5rem 0;
  color: var(--ink, #1a1a1a);
}

:scope .content-panel p {
  font-size: 1rem;
  margin: 0 0 1rem 0;
}

:scope .source-actions {
  display: flex;
  gap: 0.5rem;
}

:scope .source-btn {
  background: transparent;
  border: 1px solid var(--muted, #999);
  color: var(--muted, #666);
  padding: 0.2rem 0.6rem;
  border-radius: 4px;
  font-size: 0.85rem;
  cursor: pointer;
}

:scope .source-btn:hover {
  border-color: var(--accent, #0055aa);
  color: var(--accent, #0055aa);
}

/* Strategy Comparison */
:scope .strategy-comparison {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: stretch;
  margin-bottom: 1.5rem;
}

:scope .strategy-card {
  flex: 1;
  min-width: 280px;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 8px;
  padding: 1.5rem;
  background: #fff;
  display: flex;
  flex-direction: column;
}

:scope .strategy-card h3 {
  margin: 0 0 1rem 0;
  font-size: 1.2rem;
}

:scope .strategy-card.uplink {
  border-top: 4px solid var(--muted, #999);
}

:scope .strategy-card.downlink {
  border-top: 4px solid var(--accent, #0055aa);
}

:scope .strategy-card.highlighted {
  background: #f0f7ff;
  border-color: var(--accent, #0055aa);
}

:scope .mechanism {
  font-weight: bold;
  color: var(--ink, #1a1a1a);
  margin-bottom: 0.5rem;
}

:scope .benefits {
  margin: 1rem 0;
  padding-left: 1.2rem;
  color: var(--ink, #1a1a1a);
}

:scope .benefits li {
  margin-bottom: 0.3rem;
}

:scope .strategy-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  color: var(--muted, #999);
  font-size: 1.2rem;
  padding: 0 1rem;
}

:scope .narrative-text {
  font-size: 1rem;
  color: var(--ink, #1a1a1a);
  background: #fff;
  padding: 1rem;
  border-left: 3px solid var(--accent, #0055aa);
}

/* Responsive */
@media (max-width: 600px) {
  :scope .interaction-controls {
    flex-direction: column;
    align-items: stretch;
  }
  :scope .step-indicators {
    justify-content: center;
  }
  :scope .strategy-divider {
    padding: 0.5rem 0;
  }
}
