(function() {
  const state = {
    currentStep: 0,
    totalSteps: 3
  };

  const stepsData = [
    {
      title: "信号源识别机制",
      text: "为解决超密集组网中基带信息复制导致的终端无法判断信号来源问题，需为每个远端无线射频单元分配独立的 PRSID。",
      sources: ["S040", "S041"],
      draw: drawStep0
    },
    {
      title: "物理层增益：频率特性",
      text: "利用 5G 毫米波或高频通信波的天然指向性，增强信号的空间分辨能力。",
      sources: ["S045", "S046"],
      draw: drawStep1
    },
    {
      title: "物理层增益：天线特性",
      text: "通过大规模天线技术生成高分辨率波束，直接提升 TDOA 测距和 AOA 测角的精度。",
      sources: ["S047", "S048"],
      draw: drawStep2
    }
  ];

  const svgContent = document.getElementById('svg-content');
  const stepTitle = document.getElementById('step-title');
  const stepText = document.getElementById('step-text');
  const sourceActions = document.querySelector('.content-panel .source-actions');
  const indicators = document.querySelectorAll('.step-indicator');
  const btnPrev = document.getElementById('step-prev');
  const btnNext = document.getElementById('step-next');

  function updateUI() {
    const data = stepsData[state.currentStep];

    // Update Text
    stepTitle.textContent = data.title;
    stepText.textContent = data.text;

    // Update Sources
    sourceActions.innerHTML = '';
    data.sources.forEach(sid => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'source-btn';
      btn.dataset.source = sid;
      btn.textContent = '原文 · p.2';
      sourceActions.appendChild(btn);
    });

    // Update Indicators
    indicators.forEach((ind, idx) => {
      if (idx === state.currentStep) {
        ind.classList.add('active');
        ind.setAttribute('aria-selected', 'true');
      } else {
        ind.classList.remove('active');
        ind.setAttribute('aria-selected', 'false');
      }
    });

    // Update Buttons
    btnPrev.disabled = state.currentStep === 0;
    btnNext.disabled = state.currentStep === state.totalSteps - 1;

    // Draw SVG
    svgContent.innerHTML = '';
    data.draw(svgContent);
  }

  function drawStep0(container) {
    // UDN + PRSID: Multiple nodes, distinct IDs
    const colors = ['#0055aa', '#0077cc', '#0099ee'];
    for (let i = 0; i < 3; i++) {
      const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
      const x = 100 + i * 150;
      const y = 150;

      // Node
      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', x);
      circle.setAttribute('cy', y);
      circle.setAttribute('r', 30);
      circle.setAttribute('fill', colors[i]);
      circle.setAttribute('stroke', '#1a1a1a');
      circle.setAttribute('stroke-width', 2);

      // Label
      const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      text.setAttribute('x', x);
      text.setAttribute('y', y + 5);
      text.setAttribute('text-anchor', 'middle');
      text.setAttribute('fill', '#fff');
      text.setAttribute('font-size', '12');
      text.textContent = `PRSID-${i+1}`;

      // Signal Wave
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      path.setAttribute('d', `M${x},${y-40} Q${x+20},${y-60} ${x+40},${y-40}`);
      path.setAttribute('fill', 'none');
      path.setAttribute('stroke', '#ff9900');
      path.setAttribute('stroke-width', 2);
      path.setAttribute('stroke-dasharray', '4,4');

      g.appendChild(path);
      g.appendChild(circle);
      g.appendChild(text);
      container.appendChild(g);
    }

    const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    label.setAttribute('x', 300);
    label.setAttribute('y', 280);
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('fill', '#666');
    label.textContent = '超密集组网 (UDN) + 独立 PRSID';
    container.appendChild(label);
  }

  function drawStep1(container) {
    // mmWave Directivity
    const x = 300;
    const y = 150;

    // Base Station
    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rect.setAttribute('x', x - 40);
    rect.setAttribute('y', y - 40);
    rect.setAttribute('width', 80);
    rect.setAttribute('height', 80);
    rect.setAttribute('fill', '#0055aa');
    rect.setAttribute('stroke', '#1a1a1a');

    // Beam
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('d', `M${x},${y} L${x-100},${y-100} L${x+100},${y-100} Z`);
    path.setAttribute('fill', 'rgba(0, 85, 170, 0.3)');
    path.setAttribute('stroke', '#0055aa');

    // Target
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.setAttribute('cx', x);
    circle.setAttribute('cy', y - 120);
    circle.setAttribute('r', 10);
    circle.setAttribute('fill', '#ff9900');

    container.appendChild(rect);
    container.appendChild(path);
    container.appendChild(circle);

    const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    label.setAttribute('x', 300);
    label.setAttribute('y', 280);
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('fill', '#666');
    label.textContent = '毫米波/高频通信：指向性';
    container.appendChild(label);
  }

  function drawStep2(container) {
    // Massive MIMO
    const x = 300;
    const y = 150;

    // Antenna Array
    for (let i = 0; i < 4; i++) {
      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', x - 60 + i * 40);
      rect.setAttribute('y', y - 20);
      rect.setAttribute('width', 30);
      rect.setAttribute('height', 40);
      rect.setAttribute('fill', '#0077cc');
      rect.setAttribute('stroke', '#1a1a1a');
      container.appendChild(rect);

      // Narrow Beam from each
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      path.setAttribute('d', `M${x - 45 + i * 40},${y - 20} L${x - 55 + i * 40},${y - 100} L${x - 35 + i * 40},${y - 100} Z`);
      path.setAttribute('fill', 'rgba(0, 119, 204, 0.4)');
      path.setAttribute('stroke', '#0077cc');
      container.appendChild(path);
    }

    const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    label.setAttribute('x', 300);
    label.setAttribute('y', 280);
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('fill', '#666');
    label.textContent = '大规模天线：高分辨率波束';
    container.appendChild(label);
  }

  function nextStep() {
    if (state.currentStep < state.totalSteps - 1) {
      state.currentStep++;
      updateUI();
    }
  }

  function prevStep() {
    if (state.currentStep > 0) {
      state.currentStep--;
      updateUI();
    }
  }

  // Event Listeners
  btnNext.addEventListener('click', nextStep);
  btnPrev.addEventListener('click', prevStep);

  indicators.forEach(ind => {
    ind.addEventListener('click', (e) => {
      const step = parseInt(e.target.dataset.step, 10);
      if (!isNaN(step) && step >= 0 && step < state.totalSteps) {
        state.currentStep = step;
        updateUI();
      }
    });
  });

  // Keyboard Navigation
  document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') nextStep();
    if (e.key === 'ArrowLeft') prevStep();
  });

  // Initialize
  updateUI();
})();
